class A:
    def f(self): print('A')
class B(A):
    def f(self): print('B'); super().f()
class C(A):
    def f(self): print('C'); super().f()
class D(B, C): pass
D().f()  # B, C, A

class K:
    def __init__(self, x): self.x = x
    def __eq__(self, other): return isinstance(other, K) and self.x == other.x
    def __hash__(self): return hash(self.x)

k = K(1)
s = {k}
k.x = 2  # now membership is unreliable
